import type { BookingCache, Db } from './types.js';

export async function getBookings(
  ctx: { clientId: string },
  cache: BookingCache,
  db: Db,
): Promise<Array<{ id: string; clientId: string }>> {
  const cached = await cache.get('bookings');
  if (cached !== null) {
    return cached;
  }

  if (ctx.clientId.trim() === '') {
    throw new Error('clientId: не определён');
  }

  const rows = await db.booking.findMany({ where: { clientId: ctx.clientId } });
  await cache.set('bookings', rows);
  return rows;
}
